action.mutation:
mutation CreateFacility($payload: [FacilityCreatePayloadInput!]!) {
  mutation: createFacility(payload: $payload) { 
    id
    code
  }
}

mutation UpdateFacility($payload: [FacilityUpdatePayloadInput!]!) {
  mutation: updateFacility(payload: $payload) { 
    id
    code
  }
}

mutation DeleteFacility($payload: [FacilityDeletePayloadInput!]!) {
  mutation: deleteFacility(payload: $payload) { 
    id
    code
  }
}
